WITH valid AS (SELECT id, customer_id, account_type, balance, opened_date, status, DATE_ADD(opened_date, 62) AS opened_date_plus_62d, COALESCE(status, 'OTHER') AS status_clean FROM accounts WHERE opened_date > TO_DATE('2023-07-20') AND balance > 25000) SELECT *, LAST_VALUE(status, TRUE) OVER (PARTITION BY status ORDER BY balance, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS last_known_status, FIRST_VALUE(balance) IGNORE NULLS OVER (PARTITION BY status, account_type ORDER BY opened_date_plus_62d, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS first_known_balance, LAG(balance, 1) OVER (PARTITION BY account_type ORDER BY balance, id) AS prev_balance FROM valid;
